using System.IO; using System.Text.Json; using SaarOSS.Rechnungsprogramm.Models; namespace SaarOSS.Rechnungsprogramm.Services; public sealed class CompanySettingsService { private static readonly JsonSerializerOptions Options=new(){WriteIndented=true}; private readonly string _folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SaarOSS","Rechnungsprogramm"); private string FilePath=>Path.Combine(_folder,"company-settings.json"); public CompanySettings Load(){try{return File.Exists(FilePath)?JsonSerializer.Deserialize<CompanySettings>(File.ReadAllText(FilePath),Options)??new():new();}catch{return new();}} public void Save(CompanySettings value){Directory.CreateDirectory(_folder);var temp=FilePath+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(value,Options));File.Move(temp,FilePath,true);} }
